//! Small C# text helpers shared by the generators.

use std::fmt::Write as _;

/// Header of every generated file.
pub const HEADER: &str = "// <auto-generated>\n// Generated by ara-script from the Rust ABI and the Schema DB. Do not edit;\n// regenerate with `ARA_UPDATE_GENERATED=1 cargo test -p ara-script --test generated`.\n// </auto-generated>\n#nullable enable\n";

/// `snake_case` or `SCREAMING_SNAKE` → `PascalCase`.
pub fn pascal_snake(s: &str) -> String {
    s.split('_')
        .filter(|p| !p.is_empty())
        .map(|p| {
            let lower = p.to_ascii_lowercase();
            let mut c = lower.chars();
            c.next()
                .map(|f| f.to_ascii_uppercase().to_string() + c.as_str())
                .unwrap_or_default()
        })
        .collect()
}

/// `camelCase` → `PascalCase`.
pub fn pascal_camel(s: &str) -> String {
    let mut c = s.chars();
    c.next()
        .map(|f| f.to_ascii_uppercase().to_string() + c.as_str())
        .unwrap_or_default()
}

/// Escapes text for XML doc comments.
pub fn xml(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

/// Escapes doc text for XML and turns Markdown code spans (`` `x` ``) into `<c>x</c>`.
pub fn xml_doc(s: &str) -> String {
    let mut out = String::new();
    for (i, part) in xml(s).split('`').enumerate() {
        if i % 2 == 1 {
            out.push_str("<c>");
            out.push_str(part);
            out.push_str("</c>");
        } else {
            out.push_str(part);
        }
    }
    out
}

/// Escapes text for a C# regular string literal.
pub fn literal(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Writes an XML `<tag>` doc block from (possibly multi-line) text, indented by `indent`.
pub fn doc_tag(out: &mut String, indent: &str, tag: &str, text: &str) {
    let lines: Vec<&str> = text
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .collect();
    if lines.is_empty() {
        return;
    }
    let _ = writeln!(out, "{indent}/// <{tag}>");
    for l in lines {
        let _ = writeln!(out, "{indent}/// {}", xml_doc(l));
    }
    let _ = writeln!(out, "{indent}/// </{tag}>");
}

/// Writes a `<summary>` block.
pub fn doc(out: &mut String, indent: &str, text: &str) {
    doc_tag(out, indent, "summary", text);
}

/// A C# literal for a finite `f64` (`1`, `0.5`, `-2.25`).
pub fn number(v: f64) -> String {
    if v.is_finite() && v.fract() == 0.0 && v.abs() < 1e15 {
        format!("{v:.0}")
    } else {
        let text = format!("{v}");
        if v.is_finite() && !text.contains(['.', 'e', 'E']) {
            format!("{text}.0")
        } else {
            text
        }
    }
}
